Q: automatically download MS excel file using codeigniter with content join 3 table A: <p>Try This,</p>

<p>Controller: </p>

<pre><code>public function report(){
        $result['report_data'] = $this-&gt;Homemodel-&gt;get_report(); 
         $this-&gt;load-&gt;view('admin/reports',$result);

    }
</code></pre>

<p>Model :</p>

<pre><code>public function get_report(){
    $this-&gt;db-&gt;select('A.*,B.*,C.*')
             -&gt;from('A')
             -&gt;join('B','B.bid=A.id')
             -&gt;join('c','c.cid=A.id')
             -&gt;order_by('A.created_on', 'Desc');
                $query = $this-&gt;db-&gt;get();
                return $query-&gt;result_array();
}
</code></pre>

